def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Considers round (), square [], and curly {} brackets. Ignores other characters.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        # else ignore
    return not stack

