{"task_id": "T06", "code": "def solve(tokens):
    """Evaluate an expression given in Reverse Polish Notation.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division truncates toward zero as in typical integer division.
    """
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            else:  # division
                # Python's int division truncates toward zero when using int(a / b)
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0
