    """Run‑length encode *s*.
    Returns a list of ``[element, count]`` pairs for each maximal run of equal
    elements. The function is tolerant: if *s* is ``None`` or not an iterable of
    characters (e.g., an integer), it returns an empty list instead of raising
    an exception. ``bytes`` objects are decoded to strings using UTF‑8 (fallback
    to *latin1* on error).
    """
    # Guard against None or non‑iterable inputs.
    if s is None:
        return []
    # Decode bytes to a string.
    if isinstance(s, bytes):
        try:
            s = s.decode()
        except Exception:
            s = s.decode('latin1')
    # Accept strings directly; for other iterables (list, tuple, generator)
    # convert to a list of elements.
    if isinstance(s, str):
        iterable = s
    else:
        try:
            iterable = list(s)
        except TypeError:
            return []
    if not iterable:
        return []
    # Standard run‑length encoding.
    res = []
    prev = iterable[0]
    count = 1
    for elem in iterable[1:]:
        if elem == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = elem
            count = 1
    res.append([prev, count])
    return res

