def solve(s):
    """Run‑length encode *s*.
    The function accepts:
    * a string (standard case)
    * a ``bytes`` object – it is decoded to a string using UTF‑8 (fallback to latin‑1)
    * any other iterable (list, tuple, generator) of hashable elements.
    For non‑iterable or ``None`` inputs an empty list is returned.
    The result is a list of ``[element, count]`` pairs where *element* is the
    original item (for strings this is a one‑character ``str``).
    """
    # Guard against None and non‑iterables.
    if s is None:
        return []
    # Bytes should be treated as a textual string.
    if isinstance(s, bytes):
        try:
            s = s.decode()
        except Exception:
            s = s.decode('latin1')
    # If it's a string we can work directly.
    if isinstance(s, str):
        iterable = s
    else:
        # Try to turn any iterable into a list.
        try:
            iterable = list(s)
        except TypeError:
            return []
    if not iterable:
        return []
    # Standard run‑length encoding.
    res = []
    prev = iterable[0]
    count = 1
    for elem in iterable[1:]:
        if elem == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = elem
            count = 1
    res.append([prev, count])
    return res

