def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Accepts any iterable of comparable items; non‑iterables or items that cannot be
    compared are ignored, treating the sequence as empty for those elements.
    """
    # Convert to list if possible; otherwise treat as empty sequence
    try:
        seq = list(nums)
    except Exception:
        return 0
    # Patience sorting (O(n log n))
    tails = []  # tails[i] is the smallest possible tail of an IS of length i+1
    for x in seq:
        # Skip items that cannot be compared (e.g., None, dict)
        try:
            # Binary search for the insertion point of x in tails
            lo, hi = 0, len(tails)
            while lo < hi:
                mid = (lo + hi) // 2
                if tails[mid] < x:
                    lo = mid + 1
                else:
                    hi = mid
            if lo == len(tails):
                tails.append(x)
            else:
                tails[lo] = x
        except Exception:
            # If comparison fails, ignore this element
            continue
    return len(tails)

