    if seq is None:
        return 0
    try:
        iterator = iter(seq)
    except TypeError:
        # Not iterable, treat as single element
        seq = [seq]
    # Ensure seq is a list for length check
    seq = list(seq)
    if not seq:
        return 0
    tails = []
    for x in seq:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
