def solve(*args, **kwargs):
    """Return matrix elements in clockwise spiral order.
    Accepts matrix via first positional argument or any keyword value.
    Works for rectangular matrices (list of lists). Empty matrix returns [] .
    """
    if args:
        mat = args[0]
    elif kwargs:
        mat = next(iter(kwargs.values()))
    else:
        mat = []
    if not mat:
        return []
    # Ensure list of lists
    matrix = [list(row) for row in mat]
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1 if matrix else -1
    result = []
    while top <= bottom and left <= right:
        # Traverse top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1
        # Traverse right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            # Traverse bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            # Traverse left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1
    return result

