def solve(tokens):
    stack = []
    for t in tokens:
        if t not in '+-*/':
            stack.append(int(t))
        else:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:
                # division trunc toward zero
                if b == 0:
                    raise ZeroDivisionError
                stack.append(int(a / b))
    return stack[0] if stack else 0
